import { Product } from '../models/Product';
import { ProductCard } from '../views/ProductCart';
import { ProductDetail } from '../views/ProductDetail';
export class ProductController {
    constructor(gallerySelector, modal, cartController, api) {
        this.modal = modal;
        this.cartController = cartController;
        this.api = api;
        this.products = [];
        const gallery = document.querySelector(gallerySelector);
        if (!gallery) {
            throw new Error(`Gallery element ${gallerySelector} not found`);
        }
        this.gallery = gallery;
    }
    async loadProducts() {
        try {
            const response = (await this.api.get('/product'));
            this.products = response.items.map((item) => new Product(item.id, item.description, item.image, item.title, item.category, item.price));
            this.renderGallery();
        }
        catch (error) {
            console.error('Ошибка при загрузке товаров:', error);
        }
    }
    renderGallery() {
        this.gallery.innerHTML = '';
        this.products.forEach((product) => {
            const card = new ProductCard(product, () => this.openProductDetail(product));
            this.gallery.appendChild(card.getElement());
        });
    }
    openProductDetail(product) {
        const inCart = this.cartController.isInCart(product.id);
        const detail = new ProductDetail(product, (p) => this.cartController.addToCart(p), inCart);
        this.modal.setContent(detail.getElement());
        this.modal.open();
    }
}
