import { getTemplate } from '../utils/utils';
export class OrderSuccess {
    constructor(total, onClose) {
        this.total = total;
        this.onClose = onClose;
        this.element = this.render();
        this.bindEvents();
    }
    render() {
        const template = getTemplate('success');
        const fragment = template.content.cloneNode(true);
        const successElement = fragment.firstElementChild;
        const description = successElement.querySelector('.order-success__description');
        if (description) {
            description.textContent = `Списано ${this.total} синапсов`;
        }
        return successElement;
    }
    bindEvents() {
        const closeButton = this.element.querySelector('.order-success__close');
        if (closeButton) {
            closeButton.addEventListener('click', this.onClose);
        }
    }
    getElement() {
        return this.element;
    }
}
