import { CartView } from '../views/CartView';
export class CartController {
    constructor(modal, orderController, events, cart) {
        this.modal = modal;
        this.orderController = orderController;
        this.events = events;
        this.cart = cart;
    }
    addToCart(product) {
        this.cart.addItem(product);
        this.updateCounter();
        console.log('Товары в корзине после добавления:', this.cart.getItems());
        this.modal.close();
    }
    removeFromCart(productId) {
        this.cart.removeItem(productId);
        this.updateCounter();
        this.openCart();
    }
    openCart() {
        console.log('Товары в корзине перед открытием:', this.cart.getItems());
        const cartView = new CartView(this.cart.getItems(), (productId) => this.removeFromCart(productId), () => this.orderController.startOrder());
        this.modal.setContent(cartView.getElement());
        this.modal.open();
    }
    isInCart(productId) {
        return this.cart.getItems().some((item) => item.id === productId);
    }
    updateCounter() {
        this.events.emit('cart:updated', { items: this.cart.getItems() });
    }
}
